 /* character selection */
 .intro-layout{display:grid;grid-template-columns:1fr .88fr;gap:70px;align-items:center;max-width:1190px;margin:0 auto;padding:52px 0 62px;min-height:calc(100vh - 145px)}.intro-copy{padding:10px 0}.eyebrow{display:flex;align-items:center;gap:10px;font-size:9px;font-weight:700;letter-spacing:.22em;text-transform:uppercase;color:var(--gold)}.eyebrow:before{content:'';width:25px;height:1px;background:var(--gold)}.intro-title{font:clamp(54px,7vw,92px)/.93 var(--serif);font-weight:400;letter-spacing:-.045em;margin:28px 0 22px;color:#f1ebdb}.intro-title em{color:var(--gold2);font-weight:400}.intro-desc{max-width:465px;color:#a8b0a1;font-size:13px;line-height:1.9}.story-teaser{margin-top:42px;padding:17px 20px;border-left:2px solid var(--gold);background:linear-gradient(90deg,rgba(211,166,88,.08),transparent);max-width:430px}.story-teaser strong{display:block;color:#dbcb9f;font:italic 16px var(--serif);margin-bottom:5px}.story-teaser span{font-size:10px;color:#879183;line-height:1.7}.hero-visual{position:relative;min-height:445px;display:flex;align-items:center;justify-content:center}.hero-art{position:absolute;inset:0;overflow:hidden;border-radius:4px;background:linear-gradient(180deg,rgba(15,26,21,.02),rgba(15,26,21,.6)),radial-gradient(ellipse at 50% 35%,rgba(218,160,79,.24),transparent 37%),linear-gradient(160deg,#28392f 0%,#1c2a22 54%,#121d18 100%);border:1px solid rgba(222,198,147,.18)}.hero-art:before{content:'';position:absolute;inset:0;background:linear-gradient(0deg,#17211b 0%,transparent 42%),repeating-linear-gradient(90deg,transparent 0 57px,rgba(255,255,255,.018) 58px 59px)}.moon{position:absolute;top:56px;left:54%;width:112px;height:112px;border-radius:50%;background:radial-gradient(circle at 38% 36%,#f2d89b,#c7974f 76%);box-shadow:0 0 60px rgba(227,177,95,.3);opacity:.86}.mountain{position:absolute;bottom:66px;left:-4%;width:108%;height:230px;background:#263a30;clip-path:polygon(0 76%,12% 56%,21% 68%,37% 19%,48% 58%,62% 34%,76% 74%,87% 48%,100% 69%,100% 100%,0 100%)}.mountain.back{bottom:75px;background:#344236;opacity:.5;transform:scaleX(-1) translateY(-30px);clip-path:polygon(0 68%,18% 44%,29% 69%,47% 20%,60% 65%,77% 31%,91% 67%,100% 52%,100% 100%,0 100%)}.pine-line{position:absolute;bottom:50px;left:0;width:100%;height:118px;background:repeating-linear-gradient(90deg,transparent 0 24px,#121e18 25px 28px,transparent 29px 42px);clip-path:polygon(0 100%,0 43%,5% 78%,10% 27%,15% 77%,21% 20%,25% 80%,31% 34%,37% 79%,43% 16%,49% 77%,55% 26%,60% 84%,67% 31%,73% 80%,80% 18%,86% 79%,92% 30%,100% 72%,100% 100%)}.art-caption{position:absolute;left:26px;bottom:24px;color:#c9c4af;font:italic 14px var(--serif);letter-spacing:.02em}.art-caption small{display:block;font:8px var(--sans);letter-spacing:.17em;color:#9eaa98;margin-bottom:8px}.role-panel{grid-column:1/-1;margin-top:-3px}.section-heading{display:flex;justify-content:space-between;align-items:end;margin-bottom:17px}.section-heading h2{font:26px var(--serif);font-weight:400;margin:0;color:#e9e2d2}.section-heading span{font-size:9px;letter-spacing:.14em;color:#879183}.class-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.class-card{position:relative;text-align:left;padding:17px 17px 15px;border:1px solid rgba(232,222,197,.15);background:rgba(237,229,208,.035);min-height:142px;cursor:pointer;transition:.2s}.class-card:hover,.class-card.selected{background:rgba(211,166,88,.09);border-color:rgba(211,166,88,.64);transform:translateY(-2px)}.class-card.selected:after{content:'✓';position:absolute;right:13px;top:12px;color:var(--gold);font-size:12px}.class-icon{font-size:20px;color:var(--gold);margin-bottom:10px}.class-name{font-weight:700;font-size:12px;margin-bottom:5px;color:#eee8da}.class-desc{font-size:9px;line-height:1.6;color:#929b8c;min-height:29px}.class-stats{margin-top:12px;display:flex;gap:6px}.stat-chip{font-size:8px;color:#b1b8a8;background:rgba(255,255,255,.05);padding:4px 6px;border-radius:2px}.selection-actions{display:flex;justify-content:space-between;align-items:center;margin-top:18px}.random-btn,.text-btn{background:transparent;border:0;color:#bac2b1;font-size:10px;letter-spacing:.06em;cursor:pointer}.random-btn:hover,.text-btn:hover{color:var(--gold2)}.random-btn .die{font-size:17px;vertical-align:-2px;color:var(--gold);margin-right:7px}.primary-btn{border:0;background:var(--gold);color:#182119;padding:14px 22px;font-weight:800;font-size:10px;letter-spacing:.13em;text-transform:uppercase;cursor:pointer;transition:.18s;box-shadow:0 4px 18px rgba(0,0,0,.15)}.primary-btn:hover{background:#e5c27e;transform:translateY(-1px)}.primary-btn:disabled{opacity:.42;cursor:not-allowed;transform:none}.primary-btn .arrow{font-size:16px;margin-left:16px;vertical-align:-1px}
+/* adventure */
