    <div class="role-panel"><div class="section-heading"><h2>First, choose who you are.</h2><span>YOUR ADVENTURE STARTS HERE</span></div><div class="class-grid">${classes.map(c=>`<button class="class-card ${game.selected===c.id?'selected':''}" data-class="${c.id}"><div class="class-icon">${c.icon}</div><div class="class-name">${c.name}</div><div class="class-desc">${c.desc}</div><div class="class-stats"><span class="stat-chip">❤ ${c.hp} VITALITY</span><span class="stat-chip">${c.tag}</span></div></button>`).join('')}</div><div class="selection-actions"><button class="random-btn" id="random-class"><span class="die">⚄</span>Let the dice decide</button><button class="primary-btn" id="begin" ${game.selected?'':'disabled'}>Begin your story <span class="arrow">→</span></button></div></div>
