function beginAdventure(){const c=classes.find(x=>x.id===game.selected);if(!c)return;game={...game,view:'play',hero:c,chapter:0,hp:c.hp,maxHp:c.hp,enemy:null,choice:null,flags:[],journal:[],roll:null,turns:0,ending:null,hasLantern:false};game.journal.push({icon:'✦',text:`Your story begins. You are a ${c.name.toLowerCase()}.`});render();}
function renderAdventure(){const stage=stages[game.chapter];if(!stage)return;const enemy=game.enemy;const progress=Math.round((game.chapter/3)*100);const hpPct=Math.max(0,game.hp/game.maxHp*100);
  root.innerHTML=`<div class="adventure-layout"><section class="main-column"><div class="chapter-bar"><div><div class="chapter-label">CHAPTER <b>${stage.step}</b> &nbsp;·&nbsp; ${stage.name.toUpperCase()}</div><div class="progress-track"><div class="progress-fill" style="width:${progress}%"></div></div></div><div class="chapter-right"><strong>${String(game.chapter+1).padStart(2,'0')}</strong> / 03</div></div>
