function renderChosenPath(){const c=game.choice;return `<div class="peace-note">✦ &nbsp;${c.message}</div><div class="continue-row"><span class="continue-note">The road turns toward the Ember Vault…</span><button class="primary-btn" id="continue">Continue <span class="arrow">→</span></button></div>`}
function renderEncounter(e){if(e.hp<=0)return `<div class="enemy-defeated">✦ &nbsp;${e.resultText||e.win}<br><span style="font:9px var(--sans);color:#a7b49a;display:inline-block;margin-top:8px">FOUND: ${esc(e.loot)}</span></div><div class="continue-row"><span class="continue-note">The path ahead is yours.</span><button class="primary-btn" id="continue">Continue <span class="arrow">→</span></button></div>`;
  return `<div class="encounter-card"><div class="enemy-kicker">${e.kind}</div><div class="encounter-head"><div class="enemy-title">${e.name}</div><span class="threat-badge">⚠ ENCOUNTER</span></div><p class="enemy-desc">${e.desc}</p><div class="enemy-health-label"><span>VIGOR / RESOLVE</span><b>${e.hp} / ${e.maxHp}</b></div><div class="enemy-health-track"><div class="enemy-health-fill" style="width:${Math.max(0,e.hp/e.maxHp*100)}%"></div></div>
  ${e.last?`<div class="roll-result">${e.last}</div>`:''}<div class="encounter-actions"><button class="action-btn" data-action="attack"><div class="action-icon">⚔</div><strong>Attack</strong><span>Strike with force · +${game.hero.attack} bonus</span></button><button class="action-btn" data-action="talk"><div class="action-icon">☏</div><strong>Negotiate</strong><span>Find common ground · +${game.hero.charm} bonus</span></button><button class="action-btn" data-action="trick"><div class="action-icon">✧</div><strong>Trick</strong><span>Outwit your foe · +${game.hero.wit} bonus</span></button></div></div>`}
function renderAside(){const c=game.hero;return `<aside class="story-aside"><section class="aside-card hero-card"><div class="aside-heading">YOUR ADVENTURER <span>✦</span></div><div class="hero-id"><div class="avatar">${c.icon}</div><div><div class="hero-name">${c.name}</div><div class="hero-role">${c.role.toUpperCase()}</div></div></div><div class="hp-row"><span>VITALITY</span><b>${game.hp} / ${game.maxHp}</b></div><div class="health-track"><div class="health-fill" style="width:${Math.max(0,game.hp/game.maxHp*100)}%"></div></div><div class="hero-meters"><div class="meter"><b>+${c.attack}</b><span>ATTACK</span></div><div class="meter"><b>+${c.charm}</b><span>CHARM</span></div><div class="meter"><b>+${c.wit}</b><span>CUNNING</span></div></div>${game.hasLantern?'<div class="inventory-line"><span>✧</span> Blue-glass lantern</div>':''}</section>
  <section class="aside-card"><div class="aside-heading">THE JOURNAL <span>${game.journal.length} NOTES</span></div><div class="journal-list">${game.journal.length?game.journal.slice(-4).reverse().map(j=>`<div class="journal-item"><i>${j.icon}</i><span>${esc(j.text)}</span></div>`).join(''):'<div class="journal-empty">Your story is waiting to be written.</div>'}</div></section>
  <section class="aside-card"><div class="aside-heading">LAST DICE ROLL <span>D20</span></div><div class="die-row"><div class="die-face" id="die-face">${game.roll??'—'}</div><div class="die-caption"><strong>${game.roll?'The fates have spoken.':'Ready when you are.'}</strong>${game.roll?'A little luck changes everything.':'Every risky choice begins with a roll.'}</div></div></section></aside>`}

