function renderAside(){const c=game.hero;return `<aside class="story-aside"><section class="aside-card hero-card"><div class="aside-heading">YOUR ADVENTURER <span>✦</span></div><div class="hero-id"><div class="avatar">${c.icon}</div><div><div class="hero-name">${c.name}</div><div class="hero-role">${c.role.toUpperCase()}</div></div></div><div class="hp-row"><span>VITALITY</span><b>${game.hp} / ${game.maxHp}</b></div><div class="health-track"><div class="health-fill" style="width:${Math.max(0,game.hp/game.maxHp*100)}%"></div></div><div class="hero-meters"><div class="meter"><b>+${c.attack}</b><span>ATTACK</span></div><div class="meter"><b>+${c.charm}</b><span>CHARM</span></div><div class="meter"><b>+${c.wit}</b><span>CUNNING</span></div></div>${game.hasLantern?'<div class="inventory-line"><span>✧</span> Blue-glass lantern</div>':''}</section>
  <section class="aside-card"><div class="aside-heading">THE JOURNAL <span>${game.journal.length} NOTES</span></div><div class="journal-list">${game.journal.length?game.journal.slice(-4).reverse().map(j=>`<div class="journal-item"><i>${j.icon}</i><span>${esc(j.text)}</span></div>`).join(''):'<div class="journal-empty">Your story is waiting to be written.</div>'}</div></section>
  <section class="aside-card"><div class="aside-heading">LAST DICE ROLL <span>D20</span></div><div class="die-row"><div class="die-face" id="die-face">${game.roll??'—'}</div><div class="die-caption"><strong>${game.roll?'The fates have spoken.':'Ready when you are.'}</strong>${game.roll?'A little luck changes everything.':'Every risky choice begins with a roll.'}</div></div></section></aside>`}
function bindAdventure(){root.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choosePath(Number(b.dataset.choice)));root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>takeAction(b.dataset.action));const next=document.getElementById('continue');if(next)next.onclick=continueStory;}
function choosePath(index){const option=stages[game.chapter].choices[index];game.choice=option;game.flags.push(option.flag);game.journal.push({icon:option.icon,text:`You chose: ${option.title}.`});if(option.event){const data=enemies[option.event];game.enemy={...data,last:'',resultText:''};render();return;}if(option.heal){const before=game.hp;game.hp=Math.min(game.maxHp,game.hp+option.heal);if(option.flag==='inn'){game.hasLantern=true;game.journal.push({icon:'✧',text:'The innkeeper gives you a blue-glass lantern.'});}const gained=game.hp-before;option.message=`${option.message||'You take the easier road, and the world feels kinder for it.'}${gained?` You recover ${gained} vitality.`:''}${option.flag==='inn'?' A blue-glass lantern joins your pack.':''}`;}else{option.message=option.message||'You choose a quiet road. Sometimes the bravest thing is knowing what not to fight.';}if(option.ending){finish(option.ending);return;}render();}
function takeAction(action){const e=game.enemy;if(!e||e.hp<=0)return;const d20=1+Math.floor(Math.random()*20);const bonus=action==='attack'?game.hero.attack:action==='talk'?game.hero.charm:game.hero.wit;const aid=game.hasLantern&&e.ending&&action!=='attack'?1:0;const total=d20+bonus+aid;game.roll=d20;game.rolls=(game.rolls||0)+1;game.turns++;let text='';let damage=0;let hit=false;let threshold=action==='attack'?e.armor:e.armor-1;
  if(action==='attack'){hit=d20===20||d20!==1&&total>=threshold;if(hit){damage=2+Math.floor(d20/4)+Math.floor(Math.max(0,bonus)/2)+(d20===20?3:0);e.hp=Math.max(0,e.hp-damage);text=`Your strike lands! <b>D20 ${d20} + ${bonus} = ${total}</b> against ${threshold}. You deal <b>${damage} vigor</b>${d20===20?' — a critical hit!':''}.`;}else{text=`Your blow glances aside. <b>D20 ${d20} + ${bonus} = ${total}</b> (need ${threshold}).`;}}
  else{hit=d20===20||d20!==1&&total>=threshold;if(hit){damage=2+Math.floor(d20/4)+Math.floor(Math.max(0,bonus)/2)+(aid?1:0);e.hp=Math.max(0,e.hp-damage);text=`Your ${action==='talk'?'words':'clever feint'} find a crack in their resolve. <b>D20 ${d20} + ${bonus+aid} = ${total}</b> against ${threshold}. Their resolve falls by <b>${damage}</b>${d20===20?'; they are completely won over!':''}.`;}else{text=`They don't take the bait. <b>D20 ${d20} + ${bonus+aid} = ${total}</b> (need ${threshold}).`;}}
  if(e.hp<=0){e.resultText=action==='attack'?e.win:e.ally;game.journal.push({icon:'✦',text:`${e.name} is overcome by ${action==='attack'?'your courage':action==='talk'?'your kindness':'your cunning'}.`});game.journal.push({icon:'✧',text:`You gained ${e.loot}.`});text+=` <b>${action==='attack'?'Victory!':action==='talk'?'They agree to peace.':'The ruse succeeds.'}</b>`;}
  else if(!hit){const enemyRoll=1+Math.floor(Math.random()*20);if(enemyRoll+e.attack>=13){const wound=1+Math.floor(Math.random()*e.damage);game.hp=Math.max(0,game.hp-wound);text+=` ${e.name} counters—enemy D20 ${enemyRoll} + ${e.attack}; you lose <b>${wound} vitality</b>.`;}else{text+=` ${e.name} misses you (enemy D20 ${enemyRoll}).`;}}
  e.last=text;if(game.hp<=0){game.ending='fallen';game.view='ending';render();return;}render();const face=document.getElementById('die-face');if(face)face.classList.add('roll');}
function continueStory(){if(game.chapter===2){finish('victory');return;}game.chapter++;game.choice=null;game.enemy=null;game.roll=null;render();}
function finish(kind){game.ending=kind;game.view='ending';if(kind==='home')game.journal.push({icon:'⌂',text:'You brought the ember home to Alderwick.'});if(kind==='dawn')game.journal.push({icon:'✧',text:'At dawn, you rang the First Bell.'});render();}
function renderEnding(){const kind=game.ending;const endings={victory:{sigil:'✧',label:'THE BELL REMEMBERS',title:'A new dawn begins.',copy:game.flags.includes('dawn')?'The First Bell rings out over the hills. By morning, the village is awake—not in fear, but in hope. Your name becomes part of the song.':'The First Bell glows in your hands. Alderwick will remember the one who met the old magic with courage—and left the future to the living.'},home:{sigil:'⌂',label:'A QUIETER KIND OF BRAVERY',title:'The light comes home.',copy:'You carry a little ember back to Alderwick. The bell remains asleep, and the village windows glow warm against the night. Some victories are measured in all the things you protect.'},dawn:{sigil:'☼',label:'A NEW SONG',title:'The hills awake.',copy:'At first light, you ring the bell. Its note rolls across the hills, and people come out to meet the morning together. The old magic belongs to no one—and, somehow, that makes it everyone’s.'},fallen:{sigil:'✦',label:'THE ROAD GOES ON',title:'A story, not an end.',copy:'The forest keeps your name among its old stories. But every legend needs a next chapter—and yours is waiting whenever you are.'}};const e=endings[kind]||endings.victory;const decisionCount=game.flags.length;root.innerHTML=`<section class="ending-card"><div class="ending-sigil">${e.sigil}</div><div class="ending-label">${e.label}</div><h1 class="ending-title">${e.title}</h1><p class="ending-copy">${e.copy}${game.hasLantern&&kind!=='fallen'?' The blue lantern shines beside you, a small light that made the whole journey gentler.':''}</p><div class="ending-stats"><div><b>${decisionCount}</b>CHOICES MADE</div><div><b>${game.rolls||0}</b>DICE ROLLED</div><div><b>${game.hp}/${game.maxHp}</b>VITALITY LEFT</div></div><div><span class="result-pill">${game.hero?.name||'ADVENTURER'} · ${game.hero?.role||''}</span></div><button class="primary-btn" id="play-again">Begin another story <span class="arrow">↻</span></button></section>`;document.getElementById('play-again').onclick=resetGame;}
function resetGame(){game={view:'select',selected:null,hero:null,chapter:0,hp:0,maxHp:0,enemy:null,choice:null,flags:[],journal:[],roll:null,rolls:0,turns:0,ending:null,hasLantern:false,muted:true};render();window.scrollTo({top:0,behavior:'smooth'});}
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2100)}
document.getElementById('restart-top').onclick=()=>{resetGame();toast('A fresh adventure awaits.')};document.getElementById('sound-toggle').onclick=(e)=>{game.muted=!game.muted;e.currentTarget.textContent=game.muted?'◖))':'♫';e.currentTarget.title=game.muted?'Sound effects off':'Sound effects on';toast(game.muted?'Sound effects off':'Sound effects on');};render();

